{
  "name": "虚拟CAN总线",
  "name_en": "Virtual CAN Bus",
  "manufacturer": "",
  "description": "基于内部消息队列的非物理虚拟CAN总线组件，用于测试和仿真。它通过任意通道标识连接多个软件总线实例，在同一逻辑通道上传递CAN消息，提供可靠的消息投递与顺序保证，但不直接连接或控制真实硬件设备。",
  "description_en": "A non-physical virtual CAN bus component based on an internal message queue, intended for testing and simulation. It connects multiple software bus instances through an arbitrary channel identifier and passes CAN messages on the same logical channel, providing reliable delivery and message ordering without directly interfacing with real hardware.",
  "actions": [
    {
      "action_name": "auto-send",
      "description": "向该虚拟通道上的所有监听方发送一条CAN消息。",
      "description_en": "Send a CAN message to all listeners on this virtual channel."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭此虚拟总线实例，并在通道为空时将其移除。",
      "description_en": "Shut down this virtual bus instance and remove the channel if it becomes empty."
    },
    {
      "action_name": "auto-get_extra",
      "description": "获取该虚拟总线接口的附加信息。",
      "description_en": "Get extra information about this virtual bus interface."
    }
  ],
  "tag_hints": [
    "virtual CAN bus",
    "software simulation",
    "message queue",
    "CAN testing",
    "reliable message delivery",
    "bus emulation"
  ]
}

